sys_script_include.script:
var alertTable = Class.create();
alertTable.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    incDetails: function() {
        var parent_record = new GlideRecord('incident');
		var workNotes = '';
        var recID = this.getParameter('sysparm_recID');
        if (parent_record.get(recID)) {
            gs.addInfoMessage('hello');

            workNotes += '<style> table, th, td {border: 1px solid black;border-collapse: collapse;background-color:lightyellow;padding:2px;text-align: left;}</style><table style="width:100%">';

            // Assuming assessment responses are stored in the "Question" field
            workNotes += '<tr style="height: 50.4px;"><td style="width: 500px; height: 15.4px;"><strong>' + parent_record.number + '</strong></td>' + '<td style="text-align: center; "width: 700px; height: 15.4px;"">' + parent_record.assigned_to.getDisplayValue() + '</td>';

            // End the table
            workNotes += '</table>';

        }
        return workNotes;

    },
    type: 'alertTable'
});
